{
  "name": "ke_timer_check",
  "confidence": "medium",
  "docstring": "Advances the current pending kernel timer's elapsed counter and dispatches or forwards the associated timer entry when the expiry threshold or completion flag is reached, otherwise removes the entry from the queue.",
  "subsystem": "ke",
  "var_renames": {
    "v1": "timer_ctrl",
    "v2": "timer_ctx",
    "v3": "expiry_ticks",
    "v4": "elapsed_ticks",
    "v5": "event_arg"
  },
  "struct_hints": [
    {
      "offset": -12,
      "meaning": "container/list header preceding the timer/context object"
    },
    {
      "offset": 0,
      "meaning": "pointer to the current timer/context entry"
    },
    {
      "offset": 8,
      "meaning": "16-bit event/message argument associated with the timer"
    },
    {
      "offset": 10,
      "meaning": "8-bit elapsed tick counter"
    },
    {
      "offset": 11,
      "meaning": "completion or forced-dispatch flag"
    },
    {
      "offset": 367,
      "meaning": "8-bit expiry threshold in the target timer/context object"
    }
  ]
}
